cd /Users/guygouri/Devlab/ernlang/ern/formal && python3 - <<'EOF'
import re
L=open('Ern/Corpus/MM23H.lean',encoding='utf-8').read().split('\n')
for i,l in enumerate(L):
    if re.match(r'^(def|theorem|abbrev|instance|structure|inductive)\b',l):
        j=i-1
        if not L[j].rstrip().endswith('-/'):
            print('NO DOC',i+1,l)
        else:
            # find docstring start
            k=j
            while not L[k].lstrip().startswith('/--'): k-=1
            doc=' '.join(L[k:j+1])
            if '§' not in doc: print('NO §',i+1,l)
EOF
grep -n 'MM-0\|pass\b\|passe\|K1 (d)\|jalon' Ern/Corpus/MM23H.lean | head

